changeSet.sql:
create table chat_gespraech (
    id uuid not null constraint chat_gespraech_pk primary key,
    benutzer text not null,
    titel text not null,
    erstellt timestamptz not null,
    geaendert timestamptz not null
);
create index chat_gespraech_benutzer_ix on chat_gespraech (benutzer, geaendert desc);
create table chat_nachricht (
    id bigserial constraint chat_nachricht_pk primary key,
    gespraech_id uuid not null constraint chat_nachricht_gespraech_fk references chat_gespraech (id)
        on delete cascade,
    rolle text not null constraint chat_nachricht_rolle_ck check (rolle in ('BENUTZER', 'ASSISTENT')),
    inhalt text not null,
    werkzeuge jsonb,
    quellen jsonb,
    tokens_ein int constraint chat_nachricht_tokens_ein_ck check (tokens_ein >= 0),
    tokens_aus int constraint chat_nachricht_tokens_aus_ck check (tokens_aus >= 0),
    status text constraint chat_nachricht_status_ck check (status in ('OK', 'FEHLER', 'ABGEBROCHEN')),
    zeit timestamptz not null,
    constraint chat_nachricht_status_rolle_ck check ((rolle = 'BENUTZER') = (status is null))
);
create index chat_nachricht_gespraech_ix on chat_nachricht (gespraech_id, id);
create index chat_nachricht_zeit_ix on chat_nachricht (zeit);
-- Rate-Limit (Req 5.5): Fragen eines Gesprächs nach Zeit, nur Fragen
create index chat_nachricht_frage_ix on chat_nachricht (gespraech_id, zeit) where rolle = 'BENUTZER';
